    @Test
    fun everyGeneratedMethodReachesMockAndDecodesItsResponse() {
        val baseUrl = System.getenv("SDK_METHOD_TEST_BASE_URL") ?: return
        SdkConfig.configure(ClientConfig(baseUrl = baseUrl))
        val cases = mapper.readTree(File("test/sdk-method-cases.json")).get("cases")
        assertTrue(cases.size() > 0, "method fixture is empty")
        for (caseData in cases) {
            val owner = Class.forName(caseData.get("owner").asText())
            val methodName = caseData.get("methodName").asText()
            val method = owner.methods.first { it.name == methodName && !it.isSynthetic }
            val instance = owner.fields.firstOrNull { it.name == "INSTANCE" }?.get(null)
            val arguments = caseData.get("arguments")
            val order = caseData.get("argumentOrder")
            bodyMediaType = caseData.get("bodyMediaType")?.asText()
            bodyKind = caseData.get("bodyKind")?.asText()
            var positional = 0
            val suspending = method.parameterTypes.lastOrNull() == Continuation::class.java
            val values =
                method.genericParameterTypes
                    .take(method.parameterCount - if (suspending) 1 else 0)
                    .mapIndexed { index, type ->
                        val raw = method.parameterTypes[index]
                        when {
                            raw == ClientConfig::class.java -> SdkConfig.getConfig()
                            // Per-call options are the SDK's own, never an operation argument.
                            raw.simpleName == "RequestOptions" -> null
                            aggregate(raw) -> convert(type, arguments)
                            else -> {
                                val input =
                                    byName(arguments, method.parameters[index].name)
                                        ?: order.get(positional++)?.let {
                                            byName(arguments, it.asText())
                                        }
                                convert(type, input)
                            }
                        }
                    }
            // A stream is read up to its first event, which is when it decodes one.
            val invoke = {
                val result =
                    if (suspending) invokeSuspending(method, instance, values)
                    else method.invoke(instance, *values.toTypedArray())
                if (caseData.get("mode").asText() != "stream") {
                    result
                } else {
                    when (result) {
                        is Sequence<*> -> result.firstOrNull()
                        is Iterable<*> -> result.firstOrNull()
                        is Iterator<*> -> if (result.hasNext()) result.next() else null
                        else ->
                            if (firstOfFlow?.parameterTypes?.first()?.isInstance(result) == true) {
                                invokeSuspending(firstOfFlow, null, listOf(result))
                            } else {
                                result
                            }
                    }
                }
            }
            val response = caseData.get("response")
            val declaredError = response.get("kind").asText() == "error"
            SdkConfig.getConfig().baseUrl =
                if (declaredError) "$baseUrl/__mockStatus/${response.get("status").asInt()}"
                else baseUrl
            if (declaredError) {
                assertDeclaredError(caseData, invoke)
                continue
            }
            if (response.get("kind").asText() == "rejected") {
                assertTrue(
                    generateSequence(runCatching(invoke).exceptionOrNull()) { it.cause }
                        .any { it is SdkResponseDecodeError },
                    caseData.get("id").asText() + " decoded a body its schema refuses",
                )
                continue
            }
            var actual = invoke()
            // A method with no response body returns Unit, which reflection hands
            // back as a value rather than as the absence of one.
            if (actual == Unit) actual = null
            when (response.get("kind").asText()) {
                "empty" -> assertEquals(null, actual, caseData.get("id").asText())
                "bytes" ->
                    assertEquals(
                        response.get("byteLength").asInt(),
                        (actual as ByteArray).size,
                        caseData.get("id").asText(),
                    )
                // SSE data is text: a stream without a schema yields the frame
                // `data: null` as the text the mock wrote.
                else ->
                    if (
                        actual !is String ||
                            caseData.get("mode").asText() != "stream" ||
                            actual != mapper.writeValueAsString(response.get("expected"))
                    ) {
                        assertNull(
                            mismatch(mapper.valueToTree(actual), response.get("expected")),
                            caseData.get("id").asText() +
                                " decoded a response that differs from the mock",
                        )
                    }
            }
        }
